"""Resolve response references and their internal button-source tools."""

from __future__ import annotations

from collections.abc import Callable
from functools import partial

from rasa.mantle.content.responses import ResponseRegistry
from rasa.mantle.skills.catalog import (
    ResolvedActivationTarget,
    SkillCatalog,
    iter_resolved_activation_targets,
)
from rasa.mantle.skills.conditions import GatedTool
from rasa.mantle.skills.skill import Skill
from rasa.mantle.skills.steps import ActionStep, CollectStep, Step
from rasa.shared.constants import UTTER_PREFIX


def response_names_referenced_by_skill(
    catalog: SkillCatalog, skill_id: str
) -> frozenset[str]:
    """Return response names referenced by one skill."""
    skill = catalog.skills.get(skill_id)
    if skill is None:
        return frozenset()

    names: set[str] = set()
    _collect_skill_response_refs(skill, names)
    return frozenset(names)


def skills_referencing_responses(
    catalog: SkillCatalog,
) -> dict[str, frozenset[str]]:
    """Map each response name to the skill ids that reference it."""
    users: dict[str, set[str]] = {}
    for skill in catalog.skills.values():
        skill_id = skill.id
        names: set[str] = set()
        _collect_skill_response_refs(skill, names)
        for response_name in names:
            users.setdefault(response_name, set()).add(skill_id)
    return {name: frozenset(skill_ids) for name, skill_ids in users.items()}


def button_source_names_for_skill(
    catalog: SkillCatalog,
    registry: ResponseRegistry,
    skill_id: str,
) -> frozenset[str]:
    """Return source-tool names used by responses referenced from one skill."""
    response_names = response_names_referenced_by_skill(catalog, skill_id)
    return frozenset(
        variant.button_source
        for response_name in response_names
        for variant in registry.get_variants(response_name)
        if variant.button_source is not None
    )


def _collect_skill_response_refs(
    skill: Skill,
    names: set[str],
) -> None:
    """Record ``utter_*`` references from one skill onto *names*."""
    add = partial(_add_response_name, names)
    for target in iter_resolved_activation_targets(skill):
        _collect_resolved_target_response_refs(target, add)
    for gate in skill.tools:
        _collect_gated_tool_response_refs(gate, add)
    for trigger in skill.verbatim_triggers:
        add(trigger.response_name)


def _collect_resolved_target_response_refs(
    target: ResolvedActivationTarget,
    add: Callable[[str | None], None],
) -> None:
    """Record response references from one resolved target's steps and tool gates."""
    for step in target.steps:
        _collect_step_response_ref(step, add)
    for gate in target.tools:
        _collect_gated_tool_response_refs(gate, add)


def _collect_step_response_ref(
    step: Step,
    add: Callable[[str | None], None],
) -> None:
    """Record an ``utter_*`` reference from an action or collect step, if any."""
    if isinstance(step, ActionStep):
        add(step.action)
        return
    if isinstance(step, CollectStep):
        add(step.utterance)


def _collect_gated_tool_response_refs(
    gate: GatedTool,
    add: Callable[[str | None], None],
) -> None:
    add(gate.on_success)
    add(gate.on_failure)
    confirmation = gate.requires_confirmation
    if confirmation is None:
        return
    add(confirmation.utter_for_confirmation)
    add(confirmation.utter_on_user_denial)


def _add_response_name(names: set[str], response_name: str | None) -> None:
    if response_name is not None and response_name.startswith(UTTER_PREFIX):
        names.add(response_name)
